from decimal import Decimal, ROUND_HALF_UP

CENTS = Decimal('0.01')


def _cents(value):
    return value.quantize(CENTS, rounding=ROUND_HALF_UP)


def _fmt(value):
    if value == 0:
        value = abs(value)
    return f'{value:.2f}'


def invoice(lines, tax_rate):
    rate = Decimal(tax_rate)
    subtotal = Decimal('0')
    tax = Decimal('0')
    for row in lines:
        rounded_line = _cents(Decimal(row['unit_price']) * row['qty'])
        subtotal += rounded_line
        if row['taxable']:
            tax += _cents(rounded_line * rate)
    total = subtotal + tax
    return {'subtotal': _fmt(subtotal), 'tax': _fmt(tax), 'total': _fmt(total)}
